// Agrupa los resultados por pregunta y calcula los aciertos.
// El Vector Store devuelve los resultados EN ORDEN: 3 por pregunta (topK = 3).
// No se usa pairedItem: en este nodo apunta al índice del resultado, no al de la pregunta
// (hallazgo de la primera corrida: asignaba un solo resultado a cada pregunta).
const UMBRAL = 0.65;
const TOPK = 3;
const preguntas = $('Preguntas de evaluación').all().map(i => i.json);
const resultados = $input.all().filter(i => i.json.document);
if (resultados.length !== preguntas.length * TOPK) {
  throw new Error(`Se esperaban ${preguntas.length * TOPK} resultados y llegaron ${resultados.length}: revisar el topK o la tabla documents.`);
}
const porPregunta = {};
resultados.forEach((it, i) => {
  const idx = Math.floor(i / TOPK);
  (porPregunta[idx] = porPregunta[idx] || []).push({
    fuente: it.json.document.metadata?.archivo || 'sin nombre',
    score: Number(it.json.score || 0),
  });
});
const fecha = $now.toFormat('dd/MM/yyyy HH:mm');
const filas = preguntas.map((p, idx) => {
  const r = (porPregunta[idx] || []).sort((a, b) => b.score - a.score);
  const top1 = r[0] || { fuente: '-', score: 0 };
  const negativa = p.fuente_esperada === '(ninguna)';
  const supera = top1.score >= UMBRAL;
  const a1 = !negativa && top1.fuente === p.fuente_esperada;
  const a3 = !negativa && r.some(x => x.fuente === p.fuente_esperada);
  const ok = negativa ? !supera : (a3 && supera);
  return { fecha, n: p.n, pregunta: p.pregunta, fuente_esperada: p.fuente_esperada,
    top1_fuente: top1.fuente, top1_similitud: Number(top1.score.toFixed(3)),
    top3_fuentes: r.map(x => `${x.fuente} (${x.score.toFixed(2)})`).join(' | '),
    acierto_top1: negativa ? '-' : (a1 ? 'sí' : 'no'), acierto_top3: negativa ? '-' : (a3 ? 'sí' : 'no'),
    supera_umbral: supera ? 'sí' : 'no', resultado: ok ? 'OK' : 'FALLA' };
});
const pos = filas.filter(f => f.fuente_esperada !== '(ninguna)');
const neg = filas.filter(f => f.fuente_esperada === '(ninguna)');
const pct = (a, b) => b ? Math.round(100 * a / b) + '%' : '-';
const prom = arr => arr.length ? (arr.reduce((s, f) => s + f.top1_similitud, 0) / arr.length).toFixed(3) : '-';
filas.push({ fecha, n: 'RESUMEN', pregunta: `${filas.filter(f => f.resultado === 'OK').length}/${filas.length} casos OK`,
  fuente_esperada: `umbral ${UMBRAL}`,
  top1_fuente: `top-1: ${pct(pos.filter(f => f.acierto_top1 === 'sí').length, pos.length)} · top-3: ${pct(pos.filter(f => f.acierto_top3 === 'sí').length, pos.length)}`,
  top1_similitud: Number(prom(pos)) || 0,
  top3_fuentes: `similitud promedio cubiertas ${prom(pos)} · no cubiertas ${prom(neg)} (máx ${neg.length ? Math.max(...neg.map(f => f.top1_similitud)).toFixed(3) : '-'})`,
  acierto_top1: '', acierto_top3: '', supera_umbral: '', resultado: '' });
return filas.map(f => ({ json: f }));
